// index.ts
import getStatus, { computeAverage, EnrollmentStatus } from './gradeUtils.js';

// Interface for raw enrollee input
interface Enrollee {
    name: string;
    prelim: number;
    midterm: number;
    final: number;
}

// Interface for final report with optional remarks property
interface EligibilityReport {
    name: string;
    average: number;
    status: EnrollmentStatus;
    remarks?: string; // Optional property
}

// Starter Data
const enrollees: Enrollee[] = [
    { name: "Ana Cruz", prelim: 85, midterm: 90, final: 88 },
    { name: "Bea Santos", prelim: 70, midterm: 65, final: 60 },
    { name: "Cid Ramos", prelim: 95, midterm: 92, final: 97 },
    { name: "Dex Alonzo", prelim: 60, midterm: 55, final: 50 },
    { name: "Eli Tan", prelim: 78, midterm: 80, final: 76 }
];

// Async function returning a typed Promise
const getEnrollees = (): Promise<Enrollee[]> => {
    return new Promise((resolve) => {
        setTimeout(() => resolve(enrollees), 1000);
    });
};

// Generic function replacing .filter()
function groupBy<T>(items: T[], keyFn: (item: T) => string): Record<string, T[]> {
    return items.reduce((acc, item) => {
        const key = keyFn(item);
        if (!acc[key]) {
            acc[key] = [];
        }
        acc[key].push(item);
        return acc;
    }, {} as Record<string, T[]>);
}

// Main Async Processing Function
const processReport = async () => {
    try {
        // Demonstrate Union Type & Type Narrowing
        let batchId: string | number = "BATCH-2026" as string | number;
        if (typeof batchId === "string") {
            console.log(`Processing Batch ID: ${batchId.toUpperCase()}`);
        } else {
            console.log(`Processing Batch ID: ${batchId.toFixed(0)}`);
        }

        const data: Enrollee[] = await getEnrollees();
        console.log("\n=== IT313 Enrollment Eligibility Report (TypeScript) ===");

        // Transform data using .map()
        const reports: EligibilityReport[] = data.map((e: Enrollee) => {
            const average = computeAverage(e.prelim, e.midterm, e.final);
            const status = getStatus(average);
            
            const reportEntry: EligibilityReport = {
                name: e.name,
                average,
                status
            };

            // Set optional property for students on Probation
            if (status === EnrollmentStatus.Probation) {
                reportEntry.remarks = "Needs consultation";
            }

            return reportEntry;
        });

        // Print individual student report lines using template literals
        reports.forEach((r) => {
            const remarkText = r.remarks ? ` ${r.remarks}` : "";
            console.log(`${r.name}\n  Average: ${r.average.toFixed(2)} ${r.status}${remarkText}`);
        });

        // Use Generic groupBy to separate status groups
        const grouped = groupBy(reports, (r) => r.status);
        const passingCount = grouped[EnrollmentStatus.Passing]?.length || 0;

        // Calculate class average using .reduce()
        const totalClassAvg = reports.reduce((acc, curr) => acc + curr.average, 0) / reports.length;

        console.log(`\nClass Average: ${totalClassAvg.toFixed(2)}`);
        console.log(`Passing: ${passingCount}/${reports.length}`);

    } catch (error) {
        console.error("Error processing report:", error);
    }
};

processReport();